import{_ as l,a0 as n,w as r,s as h,ao as k,I as p,x as i,a1 as a,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"C语言数据类型是如何被大多数计算机系统所支持？ | LCTT x X-CMD","titleTemplate":false,"description":"C语言数据类型是如何被大多数计算机系统所支持？ | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"C语言数据类型是如何被大多数计算机系统所支持？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"C语言数据类型是如何被大多数计算机系统所支持？ | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20150122 How are C data types “supported directly by most computers”","title":"C语言数据类型是如何被大多数计算机系统所支持？","tag":"201504","desc":""},"relativePath":"201504/20150122 How are C data types “supported directly by most computers”.md","filePath":"[post].md"}'),o={name:"201504/20150122 How are C data types “supported directly by most computers”.md"};function d(g,s,y,C,u,m){const t=n("Link");return r(),h("div",null,[s[13]||(s[13]=k(`<h1 id="c语言数据类型是如何被大多数计算机系统所支持" tabindex="-1">C语言数据类型是如何被大多数计算机系统所支持？ <a class="header-anchor" href="#c语言数据类型是如何被大多数计算机系统所支持" aria-label="Permalink to “C语言数据类型是如何被大多数计算机系统所支持？”">​</a></h1><p>###问题：</p><p>在读K&amp;R版的<em>The C Programming Language</em>一书时，我在[介绍，第3页]看到这样一条说明：</p><blockquote><p><strong>因为C语言提供的数据类型和控制结构可以直接被大部分计算机系统所支持，所以在实现自包含程序时所需要的运行库文件一般很小。</strong></p></blockquote><p>这段黑体说明了什么？能否找到一个例子来说明C语言中的某种数据类型或控制结构不被某种计算机系统直接支持呢？</p><p>###回答:</p><p>事实上，C语言中确实有不被直接支持的数据类型。</p><p>在许多嵌入式系统中，硬件上并没有浮点运算单元。因此，如果你写出下面的代码：</p><div class="language-C"><button title="Copy Code" class="copy"></button><span class="lang">C</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">float</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> x </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1.0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">f</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, y </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2.0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">f</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> x </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> y;</span></span></code></pre></div><p>可能会被转化成下面这种形式：</p><div class="language-C"><button title="Copy Code" class="copy"></button><span class="lang">C</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">unsigned</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> x </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 0x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3f800000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, y </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 0x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">40000000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> _float_add</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(x, y);</span></span></code></pre></div><p>然后编译器或标准库必须提供&#39;_float_add()&#39;的具体实现，这会占用嵌入式系统的内存空间。依此去计算代码在某个微型系统（译者注：也就是指微型嵌入式系统）的实际字节数，也会发现有所增加。</p><p>另一个常见的例子是64位整型数（C语言标准中&#39;long long&#39;类型是1999年之后才出现的），这种类型在32位系统上也不能直接使用。古董级的SPARC系统则不支持整型乘法，所以在运行时必须提供乘法的实现。当然，还有一些其它例子。</p><p>####其它语言</p><p>相比起来，其它编程语言有更加复杂的基本类型。</p><p>比如，Lisp中的symbol需要大量的运行时实现支持，就像Lua中的table、Python中的string、Fortran中的array，等等。在C语言中等价的类型通常要么不属于标准库（C语言没有标准symbol或table），要么更加简单，而且并不需要那么多的运行时支持（C语言中的array基本上就是指针，以NULL结尾的字符串实现起来也很简单）。</p><p>####控制结构</p><p>异常处理是C语言中没有的一种控制结构。非局部的退出只有&#39;setjmp()&#39;和&#39;longjmp()&#39;两种，只能提供保存和恢复某些部分的处理器状态。相比之下，C++运行时环境必须先遍历函数调用栈，然后调用析构函数和异常处理函数。</p><hr>`,19)),p("p",null,[s[1]||(s[1]=i("via:",-1)),a(t,{href:"http://stackoverflow.com/questions/27977522/how-are-c-data-types-supported-directly-by-most-computers/27977605#27977605"},{default:e(()=>[...s[0]||(s[0]=[i("stackoverflow",-1)])]),_:1})]),p("p",null,[s[5]||(s[5]=i("作者：",-1)),a(t,{href:"http://stackoverflow.com/users/82294/dietrich-epp"},{default:e(()=>[...s[2]||(s[2]=[i("Dietrich Epp",-1)])]),_:1}),s[6]||(s[6]=i(" 译者：",-1)),a(t,{href:"https://github.com/KayGuoWhu"},{default:e(()=>[...s[3]||(s[3]=[i("KayGuoWhu",-1)])]),_:1}),s[7]||(s[7]=i(" 校对：",-1)),a(t,{href:"https://github.com/wxy"},{default:e(()=>[...s[4]||(s[4]=[i("wxy",-1)])]),_:1})]),p("p",null,[s[10]||(s[10]=i("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[8]||(s[8]=[i("LCTT",-1)])]),_:1}),s[11]||(s[11]=i(" 原创翻译，",-1)),a(t,{href:"http://linux.cn/"},{default:e(()=>[...s[9]||(s[9]=[i("Linux中国",-1)])]),_:1}),s[12]||(s[12]=i(" 荣誉推出",-1))])])}const F=l(o,[["render",d]]);export{b as __pageData,F as default};
